package com.nextrade.domain.risk; import com.nextrade.common.valueobject.*; import java.math.*;
public record RiskLimits(Money maxOrderNotional,Money maxDailyLoss,Quantity maxOrderQuantity,int maxOpenOrders){public RiskLimits{if(maxOrderNotional==null||maxOrderNotional.isNegative())throw new IllegalArgumentException("maxOrderNotional");if(maxDailyLoss==null||maxDailyLoss.isNegative())throw new IllegalArgumentException("maxDailyLoss");if(maxOrderQuantity==null||maxOrderQuantity.isZero())throw new IllegalArgumentException("maxOrderQuantity");if(maxOpenOrders<1)throw new IllegalArgumentException("maxOpenOrders");}public static RiskLimits conservative(java.util.Currency c){return new RiskLimits(new Money(BigDecimal.valueOf(100000),c),new Money(BigDecimal.valueOf(10000),c),new Quantity(BigDecimal.valueOf(10000)),100);}}
